# Hypothesis: Draw L-shape + corner
# For test input, minority is 7 at position (3,0)

def generate_output(input_grid):
    NR, NC = len(input_grid), len(input_grid[0])

    # Find minority value (least frequent non-zero)
    counts = {}
    for row in input_grid:
        for val in row:
            if val > 0:
                counts[val] = counts.get(val, 0) + 1

    min_val = min(counts.values())
    minority_positions = [(r,c) for r in range(NR) for c in range(NC) 
                          for val in [input_grid[r][c]] if val > 0 and counts[val] == min_val]

    # Get the first minority position
    r_min, c_min = minority_positions[0]
    minority = input_grid[r_min][c_min]

    # Generate 2x output
    out_R, out_C = NR * 2, NC * 2
    output = [[0] * out_C for _ in range(out_R)]

    for r in range(out_R):
        for c in range(out_C):
            # L-shape rule adapted for output grid
            if r == r_min * 2 and c >= c_min:
                output[r][c] = minority
            elif r >= r_min * 2 and c == c_min * 2:
                output[r][c] = minority
            elif r == out_R - 1 and c == out_C - 1:
                output[r][c] = minority

    return output

